/**
 * Which GRN API operations the grower MCP server offers as tools, and how
 * (docs/grn-mcp-server.md, "Tools").
 *
 * Every operation in the spec becomes a tool unless it is listed in EXCLUDED
 * with a reason. The list is checked against the spec in the tests: a new
 * endpoint is a new tool by default, and an exclusion for an operation that no
 * longer exists fails the build rather than lingering.
 */

import generated from './generated/operations.json' with { type: 'json' };

export const EXCLUDED = {
  // Generated by a model. The assistant calling these tools is the model.
  generateWeeklyPlan: 'calls an AI model',
  generateGardenReview: 'calls an AI model',
  getDerivedFeed: 'can generate an AI summary',
  // Agent tasks are instructions a Pro worker later runs through a model.
  listAgentTasks: 'agent tasks run through an AI model',
  createAgentTask: 'agent tasks run through an AI model',
  updateAgentTaskStatus: 'agent tasks run through an AI model',
  // A key must never manage keys: a leaked key could otherwise mint more.
  listApiKeys: 'key management stays in the app',
  getApiKey: 'key management stays in the app',
  createApiKey: 'key management stays in the app',
  updateApiKey: 'key management stays in the app',
  deleteApiKey: 'key management stays in the app',
  listMyApiAccessRequests: 'key management stays in the app',
  createApiAccessRequest: 'key management stays in the app',
  // Reviewer-only; the operator MCP server (services/mcp-api) has these.
  adminListApiAccessRequests: 'admin only',
  adminApproveApiAccessRequest: 'admin only',
  adminDenyApiAccessRequest: 'admin only',
  // Not grower actions.
  handleStripeWebhook: 'called by Stripe only',
  trackProEvent: "the app's own usage analytics"
};

/** Tags whose results other growers can see. */
const SHARED_TAGS = new Set(['Listings', 'Requests', 'Claims']);
const DESCRIPTION_LIMIT = 1500;

/**
 * Operations that accept an Idempotency-Key header. The MCP schema requires
 * the key for them even where the API leaves it optional: without one, a
 * retry after a lost response would post the same listing or request twice.
 */
export function takesIdempotencyKey(operation) {
  return operation.parameters.some((p) => p.in === 'header' && p.argument === 'idempotencyKey');
}

/** `listMyCrops` → `list_my_crops`. */
export function toolName(operationId) {
  return operationId
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2')
    .toLowerCase();
}

function describe(operation) {
  const notes = [];
  if (operation.public) notes.push('Public: works the same for anyone.');
  if (operation.tags.includes('Pro')) notes.push('Needs a Pro plan; on another plan the API answers 403 and says so.');
  if (operation.tags.includes('Grower Only')) notes.push('For growers; a gatherer account gets 403.');
  if (operation.method !== 'GET' && operation.tags.some((t) => SHARED_TAGS.has(t))) {
    notes.push('Other growers can see the result: confirm the details with the person first.');
  }
  if (takesIdempotencyKey(operation)) {
    notes.push('idempotencyKey is required: a new unique value for each change, and the same value when retrying it, so a retry never repeats the change.');
  }
  const text = [operation.summary, operation.description, notes.join(' ')].filter(Boolean).join('\n\n');
  return text.length > DESCRIPTION_LIMIT ? `${text.slice(0, DESCRIPTION_LIMIT - 1)}…` : text;
}

/** The tool's input: path, query and header parameters by name, and the request body as `body`. */
export function inputSchemaFor(operation) {
  const properties = {};
  const required = [];
  for (const parameter of operation.parameters) {
    const idempotency = parameter.in === 'header' && parameter.argument === 'idempotencyKey';
    properties[parameter.argument] = {
      ...parameter.schema,
      // The API trims the header and treats a blank one as missing, which would
      // skip deduplication; so a key must have a non-space character.
      ...(idempotency ? { minLength: 1, pattern: '\\S' } : {}),
      ...(parameter.description ? { description: parameter.description } : {})
    };
    if (parameter.required || (parameter.in === 'header' && parameter.argument === 'idempotencyKey')) {
      required.push(parameter.argument);
    }
  }
  if (operation.body) {
    properties.body = {
      ...operation.body.schema,
      ...(operation.body.description ? { description: operation.body.description } : {})
    };
    if (operation.body.required) required.push('body');
  }
  return { type: 'object', properties, ...(required.length ? { required } : {}) };
}

/**
 * idempotentHint promises that repeating a call has no further effect. That
 * holds for reads, deletes, writes that require an idempotency key (see
 * takesIdempotencyKey), and PUTs the spec tags Idempotent. A POST is not
 * idempotent on a tag alone: without a key the API makes a new record each time.
 */
function annotationsFor(operation) {
  const read = operation.method === 'GET';
  const idempotent =
    read ||
    operation.method === 'DELETE' ||
    takesIdempotencyKey(operation) ||
    (operation.method === 'PUT' && operation.tags.includes('Idempotent'));
  return {
    readOnlyHint: read,
    destructiveHint: operation.method === 'DELETE',
    idempotentHint: idempotent,
    openWorldHint: false
  };
}

export function buildCatalog(operations = generated.operations) {
  const known = new Set(operations.map((o) => o.operationId));
  const stale = Object.keys(EXCLUDED).filter((id) => !known.has(id));
  if (stale.length) throw new Error(`EXCLUDED names operations the spec no longer has: ${stale.join(', ')}`);

  const tools = operations
    .filter((operation) => !(operation.operationId in EXCLUDED))
    .map((operation) => ({
      name: toolName(operation.operationId),
      title: operation.summary ?? operation.operationId,
      description: describe(operation),
      inputSchema: inputSchemaFor(operation),
      annotations: annotationsFor(operation),
      operation
    }));
  const names = tools.map((t) => t.name);
  const clash = names.find((name, index) => names.indexOf(name) !== index);
  if (clash) throw new Error(`Two operations map to the tool name ${clash}`);
  return {
    tools,
    excluded: operations
      .filter((operation) => operation.operationId in EXCLUDED)
      .map((operation) => ({ operationId: operation.operationId, reason: EXCLUDED[operation.operationId] }))
  };
}
